-- Generated by npm run db:bundle. Do not edit this copy.
-- Test in staging first. Run in Supabase SQL Editor as the trusted database owner.
-- Installs checkout storage, access restrictions and owner-confirmed kg stock metadata.
-- Does not create customer orders or send notifications. Does not change product prices.
-- All setup changes are atomic; an error rolls the entire setup back.
begin;
select pg_advisory_xact_lock(20261012,1);

-- Source: scripts/20261002_catalog_access.sql
-- STAGING FIRST. Review metadata-only audit output and take a schema backup first.
-- No customer rows, prices, units or stock levels are changed or inferred here.
-- Apply before 20261002_secure_commerce.sql. Do not apply automatically at startup.

alter table public.products add column if not exists sale_unit text;
alter table public.products add column if not exists stock_quantity numeric;
alter table public.products add column if not exists pack_weight_kg numeric;
alter table public.products add column if not exists variant_label text;

do $$ begin
  if not exists(select 1 from pg_constraint where conrelid='public.products'::regclass and conname='catalog_sale_metadata_valid') then
    alter table public.products add constraint catalog_sale_metadata_valid check (
      (sale_unit is null or sale_unit in ('kg','pack')) and
      (stock_quantity is null or (stock_quantity >= 0 and stock_quantity < 1000000000)) and
      (pack_weight_kg is null or (pack_weight_kg > 0 and pack_weight_kg < 1000000)) and
      (sale_unit is distinct from 'pack' or stock_quantity is null or stock_quantity=trunc(stock_quantity))
    ) not valid;
  end if;
end $$;

-- Catalog/reviews are publicly read through explicitly projected API responses.
-- Browsers never require direct table permissions, even when signed into Supabase.
do $$ declare item text; field text; begin
  foreach item in array array['products','orders','delivery_settings','delivery_areas_charges','delivery_location'] loop
    if to_regclass('public.' || item) is not null then
      execute format('alter table public.%I enable row level security', item);
      execute format('revoke all on table public.%I from public, anon, authenticated', item);
      for field in select column_name from information_schema.columns where table_schema='public' and table_name=item loop
        execute format('revoke select (%I), insert (%I), update (%I), references (%I) on table public.%I from public, anon, authenticated', field, field, field, field, item);
      end loop;
      execute format('grant select, insert, update, delete on table public.%I to service_role', item);
      if exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=item) then
        execute format('alter publication supabase_realtime drop table public.%I', item);
      end if;
    end if;
  end loop;
end $$;

-- Existing permissive Storage policies cannot override restrictive policies.
-- Public image downloads remain available when the bucket itself is public.
-- With the dashboard removed, image mutations are trusted operational actions only.
do $$ begin
  if to_regclass('storage.objects') is not null then
    drop policy if exists storefront_product_images_no_insert on storage.objects;
    drop policy if exists storefront_product_images_no_update on storage.objects;
    drop policy if exists storefront_product_images_no_delete on storage.objects;
    create policy storefront_product_images_no_insert on storage.objects as restrictive for insert to anon, authenticated with check (bucket_id <> 'product-images');
    create policy storefront_product_images_no_update on storage.objects as restrictive for update to anon, authenticated using (bucket_id <> 'product-images') with check (bucket_id <> 'product-images');
    create policy storefront_product_images_no_delete on storage.objects as restrictive for delete to anon, authenticated using (bucket_id <> 'product-images');
  end if;
end $$;

-- REQUIRED owner-reviewed staging data setup, performed separately:
-- Populate sale_unit, stock_quantity and (for packs) pack_weight_kg using source
-- stock/pricing records; never bulk-set kg or derive a pack weight from quantity.
-- Supply variant_label for duplicate rice names from real product specifications.
-- Validate catalog_sale_metadata_valid after reviewed backfill.


-- Source: scripts/20261002_secure_commerce.sql
-- Additive migration. Review/apply to an isolated staging database first.
-- Requires 20261002_catalog_access.sql and owner-reviewed sale_unit/stock_quantity.
-- Does NOT modify/backfill legacy orders or infer inventory/pack sizes.

create table if not exists public.secure_orders (
  id text primary key check (id ~ '^BDEC-[a-f0-9]{32}$'),
  document jsonb not null,
  checkout_context uuid not null unique,
  idempotency_key text not null,
  request_hash text not null check (request_hash ~ '^[a-f0-9]{64}$'),
  order_access_hash text not null check (order_access_hash ~ '^[a-f0-9]{64}$'),
  access_expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  receipt_last_sent_at timestamptz,
  receipt_day date,
  receipt_count integer not null default 0,
  unique (checkout_context, idempotency_key)
);
create table if not exists public.customer_reviews (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(name) between 2 and 80),
  rating integer not null check (rating between 1 and 5),
  city text not null default '' check (length(city) <= 100),
  review text not null check (length(review) between 10 and 2000),
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  verified_purchase boolean not null default false,
  is_synthetic boolean not null default false,
  order_id text references public.secure_orders(id),
  created_at timestamptz not null default now(),
  check (not verified_purchase or order_id is not null)
);
create unique index if not exists one_review_per_order on public.customer_reviews(order_id) where order_id is not null;
create table if not exists public.api_rate_limits (
  key text primary key,
  count integer not null,
  expires_at timestamptz not null
);
create index if not exists api_rate_limit_expiry on public.api_rate_limits(expires_at);

alter table public.secure_orders enable row level security;
alter table public.customer_reviews enable row level security;
alter table public.api_rate_limits enable row level security;
revoke all on public.secure_orders, public.customer_reviews, public.api_rate_limits from public, anon, authenticated;
grant select, insert, update, delete on public.secure_orders, public.customer_reviews, public.api_rate_limits to service_role;
grant select, update (stock_quantity) on public.products to service_role;

create or replace function public.consume_api_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_count integer; v_expiry timestamptz;
begin
  if length(p_key) > 100 or p_limit < 1 or p_limit > 10000 or p_window_seconds < 1 or p_window_seconds > 3600 then raise exception 'INVALID_LIMIT'; end if;
  delete from public.api_rate_limits where key in (select key from public.api_rate_limits where expires_at < now() limit 100);
  insert into public.api_rate_limits as limits(key,count,expires_at)
  values(p_key,1,now()+make_interval(secs=>p_window_seconds))
  on conflict(key) do update set
    count=case when limits.expires_at <= now() then 1 else limits.count+1 end,
    expires_at=case when limits.expires_at <= now() then now()+make_interval(secs=>p_window_seconds) else limits.expires_at end
  returning count,expires_at into v_count,v_expiry;
  return jsonb_build_object('allowed',v_count<=p_limit,'retry_after',greatest(1,ceil(extract(epoch from (v_expiry-now())))));
end $$;

create or replace function public.place_secure_order(p_order jsonb)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  v_existing public.secure_orders%rowtype;
  v_item jsonb; v_product jsonb; v_document jsonb; v_items jsonb := '[]'::jsonb;
  v_quantity numeric; v_price numeric; v_subtotal numeric := 0; v_fee numeric;
  v_unit text; v_name text; v_seen text[] := '{}';
begin
  if jsonb_typeof(p_order->'document'->'items') is distinct from 'array' or jsonb_array_length(p_order->'document'->'items') not between 1 and 50 then raise exception 'INVALID_CART'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_order->>'checkout_context',0));
  select * into v_existing from public.secure_orders where checkout_context=(p_order->>'checkout_context')::uuid;
  if found then
    if v_existing.request_hash <> p_order->>'request_hash' or v_existing.idempotency_key <> p_order->>'idempotency_key' then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
    return jsonb_build_object('record',to_jsonb(v_existing),'created',false);
  end if;
  for v_item in select value from jsonb_array_elements(p_order->'document'->'items') order by value->>'id' loop
    if v_item->>'id'=any(v_seen) then raise exception 'INVALID_CART'; end if;
    v_seen := array_append(v_seen,v_item->>'id');
    select to_jsonb(p) into strict v_product from public.products p where p.id::text=v_item->>'id' for update;
    v_unit := v_product->>'sale_unit';
    v_quantity := (v_item->>'quantity')::numeric;
    if v_unit is null or v_unit not in ('kg','pack') or v_product->>'stock_quantity' is null or v_quantity is null or v_quantity::text in ('NaN','Infinity','-Infinity') or v_quantity <= 0 or v_quantity > 100
      or (v_unit='pack' and (v_quantity<>trunc(v_quantity) or coalesce((v_product->>'pack_weight_kg')::numeric,0)<=0))
      or (v_unit='kg' and v_quantity*10<>trunc(v_quantity*10))
      or (v_product->>'stock_quantity')::numeric<v_quantity then raise exception 'STOCK_CHANGED'; end if;
    if lower(coalesce(v_product->>'out_of_stock','false'))='true' or lower(coalesce(v_product->>'status','')) in ('out of stock','out-of-stock','sold out') then raise exception 'STOCK_CHANGED'; end if;
    if v_product->>'price' is null or v_item->>'price' is null or replace(v_product->>'price',',','') !~ '^[0-9]+(\.[0-9]{1,2})?$' then raise exception 'PRICE_CHANGED'; end if;
    v_price := replace(v_product->>'price',',','')::numeric;
    if v_price<=0 or v_price<>(v_item->>'price')::numeric then raise exception 'PRICE_CHANGED'; end if;
    v_name := coalesce(v_product->>'product name',v_product->>'name','');
    if nullif(v_product->>'variant_label','') is not null then v_name:=v_name||' — '||(v_product->>'variant_label'); end if;
    v_items := v_items || jsonb_build_array(v_item || jsonb_build_object('name',v_name,'price',v_price,'unit',case when v_unit='kg' then 'Kg' else 'Pack' end,'saleUnit',v_unit,'packWeightKg',v_product->'pack_weight_kg'));
    v_subtotal := v_subtotal + v_price*v_quantity;
    update public.products set stock_quantity=stock_quantity-v_quantity where id::text=v_item->>'id';
  end loop;
  v_subtotal:=round(v_subtotal,2);
  v_fee := (p_order->'document'->>'deliveryCharges')::numeric;
  if v_fee is null or v_fee::text in ('NaN','Infinity','-Infinity') or v_fee<0 or v_fee>100000 or v_fee<>round(v_fee,2) then raise exception 'INVALID_FEE'; end if;
  if p_order->'document'->>'fulfillmentType'='pickup' then v_fee:=0; end if;
  v_document := p_order->'document' || jsonb_build_object('items',v_items,'subtotal',v_subtotal,'deliveryCharges',v_fee,'discount',0,'total',v_subtotal+v_fee,'status','Order Placed','paymentStatus','unpaid');
  insert into public.secure_orders(id,document,checkout_context,idempotency_key,request_hash,order_access_hash,access_expires_at)
  values(p_order->>'id',v_document,(p_order->>'checkout_context')::uuid,p_order->>'idempotency_key',p_order->>'request_hash',p_order->>'order_access_hash',(p_order->>'access_expires_at')::timestamptz)
  returning * into v_existing;
  return jsonb_build_object('record',to_jsonb(v_existing),'created',true);
exception when no_data_found or too_many_rows then raise exception 'STOCK_CHANGED';
end $$;

create or replace function public.claim_order_receipt(p_order_id text)
returns boolean language plpgsql security invoker set search_path = '' as $$
declare v_id text;
begin
  update public.secure_orders set receipt_last_sent_at=now(),receipt_day=current_date,
    receipt_count=case when receipt_day=current_date then receipt_count+1 else 1 end
  where id=p_order_id and (receipt_last_sent_at is null or receipt_last_sent_at < now()-interval '10 minutes')
    and (receipt_day is null or receipt_day<>current_date or receipt_count<3)
  returning id into v_id;
  return v_id is not null;
end $$;

revoke all on function public.consume_api_rate_limit(text,integer,integer),public.place_secure_order(jsonb),public.claim_order_receipt(text) from public,anon,authenticated;
grant execute on function public.consume_api_rate_limit(text,integer,integer),public.place_secure_order(jsonb),public.claim_order_receipt(text) to service_role;


-- Source: scripts/20261011_confirm_kg_catalog.sql
-- Owner confirmed 2026-10-11: prices are per kg; legacy quantity / 10 is kg stock.
-- Staging first. Requires both 20261002 migrations. Does not change prices/orders.

create or replace function public.sync_catalog_inventory()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare v_legacy numeric; v_quantity_changed boolean; v_stock_changed boolean;
begin
  if new.sale_unit is null then new.sale_unit := 'kg'; end if;
  if new.sale_unit <> 'kg' then return new; end if;
  if replace(btrim(new.quantity),',','') ~ '^[0-9]+(\.[0-9]+)?$' then
    v_legacy := replace(btrim(new.quantity),',','')::numeric / 10;
  end if;
  if tg_op = 'INSERT' then
    if new.stock_quantity is null then new.stock_quantity := v_legacy;
    else new.quantity := (new.stock_quantity * 10)::text; end if;
  else
    v_quantity_changed := new.quantity is distinct from old.quantity;
    v_stock_changed := new.stock_quantity is distinct from old.stock_quantity;
    if v_quantity_changed then
      if v_legacy is null then raise exception 'INVALID_INVENTORY'; end if;
      if v_stock_changed and new.stock_quantity is distinct from v_legacy then raise exception 'CONFLICTING_INVENTORY'; end if;
      new.stock_quantity := v_legacy;
    elsif v_stock_changed then
      if new.stock_quantity is null then raise exception 'INVALID_INVENTORY'; end if;
      new.quantity := (new.stock_quantity * 10)::text;
    elsif new.stock_quantity is null then new.stock_quantity := v_legacy;
    end if;
  end if;
  return new;
end $$;
revoke all on function public.sync_catalog_inventory() from public, anon, authenticated;

-- Keep explicit metadata and already-deducted inventory; reruns never reset stock.
update public.products set sale_unit = 'kg' where sale_unit is null;
update public.products set stock_quantity = replace(btrim(quantity),',','')::numeric / 10
where sale_unit = 'kg' and stock_quantity is null
  and replace(btrim(quantity),',','') ~ '^[0-9]+(\.[0-9]+)?$';

drop trigger if exists catalog_inventory_sync on public.products;
create trigger catalog_inventory_sync before insert or update of quantity, stock_quantity, sale_unit
on public.products for each row execute function public.sync_catalog_inventory();

-- This legacy table also contains customer addresses; it is never a public feed.
do $$ declare field text; begin
  if to_regclass('public.delivery_location') is not null then
    alter table public.delivery_location enable row level security;
    revoke all on table public.delivery_location from public, anon, authenticated;
    for field in select column_name from information_schema.columns where table_schema='public' and table_name='delivery_location' loop
      execute format('revoke select (%I), insert (%I), update (%I), references (%I) on table public.delivery_location from public, anon, authenticated',field,field,field,field);
    end loop;
    grant select, insert, update, delete on table public.delivery_location to service_role;
    if exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='delivery_location') then
      alter publication supabase_realtime drop table public.delivery_location;
    end if;
  end if;
end $$;
notify pgrst, 'reload schema';


-- Source: scripts/20261014_order_dashboard.sql
-- Additive compatibility bridge. Existing orders are not backfilled automatically.

create table if not exists public.order_dashboard_links (
  secure_order_id text primary key references public.secure_orders(id),
  legacy_row_id bigint not null unique references public.orders(id),
  legacy_order_id integer not null unique
);
create table if not exists public.staff_notification_outbox (
  order_id text primary key references public.secure_orders(id),
  attempts integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  lease_token uuid,
  lease_until timestamptz,
  sent_at timestamptz,
  last_error text
);
alter table public.order_dashboard_links enable row level security;
alter table public.staff_notification_outbox enable row level security;
revoke all on public.order_dashboard_links,public.staff_notification_outbox from public,anon,authenticated;
grant select,insert,update,delete on public.order_dashboard_links,public.staff_notification_outbox to service_role;
grant select,insert on public.orders to service_role;
-- The legacy table uses an identity/serial id; grant only its own sequence.
do $$ declare s text; begin
 s:=pg_get_serial_sequence('public.orders','id');
 if s is not null then execute format('grant usage,select on sequence %s to service_role',s); end if;
end $$;

create or replace function public.project_order_to_dashboard(p_order_id text)
returns integer language plpgsql security invoker set search_path='' as $$
declare d jsonb; stamp timestamptz; n integer; row_id bigint; meta jsonb;
begin
 -- Lock the source before the destination in every caller. No stock changes here.
 select document,created_at into strict d,stamp from public.secure_orders where id=p_order_id for update;
 select legacy_order_id into n from public.order_dashboard_links where secure_order_id=p_order_id;
 if found then return n; end if;
 -- Serialize with other legacy inserts while allocating an integer dashboard ID.
 lock table public.orders in share row exclusive mode;
 select greatest(100000,coalesce(max("order id"),99999)+1) into n from public.orders;
 meta:=jsonb_build_object(
  'secureOrderId',p_order_id,'address',d->'customer'->'address','fulfillmentType',d->'fulfillmentType',
  'city',d->'customer'->'city','area',d->'customer'->'area','email',d->'customer'->'email',
  'deliveryDetails',d->'deliveryDetails','paymentMethod',d->'paymentMethod',
  'subtotal',d->'subtotal','deliveryCharges',d->'deliveryCharges','discount',d->'discount','total',d->'total',
  'deliveryDate',d->'deliveryDate','deliverySlot',d->'deliverySlot','status',d->'status',
  'statusHistory',d->'statusHistory','latitude',d->'customer'->'latitude','longitude',d->'customer'->'longitude',
  'distanceKm',d->'deliveryDetails'->'distanceKm','items',d->'items');
 insert into public.orders(created_at,"order id","customer name","contact number","customer address",date,time,
   "Price","Delivery charges","Order pricing","delivery latitude","delivery longitude","Order status")
 values(stamp,n,d->'customer'->>'name',d->'customer'->>'phone',
   coalesce(d->'customer'->>'address','')||' | METADATA:'||meta::text,
   (stamp at time zone 'UTC')::date,(to_char(stamp at time zone 'UTC','HH24:MI:SS')||'+00')::timetz,
   (d->>'total')::numeric,(d->>'deliveryCharges')::numeric,(d->>'subtotal')::numeric,
   (d->'customer'->>'latitude')::double precision,(d->'customer'->>'longitude')::double precision,lower(d->>'status'))
 returning id into row_id;
 insert into public.order_dashboard_links values(p_order_id,row_id,n);
 insert into public.staff_notification_outbox(order_id) values(p_order_id) on conflict do nothing;
 return n;
end $$;

create or replace function public.on_secure_order_created()
returns trigger language plpgsql security invoker set search_path='' as $$
begin perform public.project_order_to_dashboard(new.id); return new; end $$;
drop trigger if exists secure_order_dashboard on public.secure_orders;
create trigger secure_order_dashboard after insert on public.secure_orders for each row execute function public.on_secure_order_created();

-- Status changes made in the owner's separate dashboard also reach token-protected tracking.
create or replace function public.sync_dashboard_order_status()
returns trigger language plpgsql security invoker set search_path='' as $$
declare s text;
begin
 s:=case lower(trim(new."Order status")) when 'order placed' then 'Order Placed' when 'confirmed' then 'Confirmed'
 when 'processing' then 'Processing' when 'preparing' then 'Preparing' when 'out for delivery' then 'Out for Delivery'
 when 'delivered' then 'Delivered' when 'cancelled' then 'Cancelled' when 'canceled' then 'Cancelled' else null end;
 if s is not null then
 update public.secure_orders o set document=jsonb_set(jsonb_set(o.document,'{status}',to_jsonb(s)),
  '{statusHistory}',coalesce(o.document->'statusHistory','[]'::jsonb)||jsonb_build_array(jsonb_build_object('status',s,'time',now(),'detail','Updated by store.')))
 from public.order_dashboard_links l where l.legacy_row_id=new.id and l.secure_order_id=o.id and o.document->>'status' is distinct from s;
 end if;
 return new;
end $$;
drop trigger if exists dashboard_order_status on public.orders;
create trigger dashboard_order_status after update of "Order status" on public.orders for each row
 when (old."Order status" is distinct from new."Order status") execute function public.sync_dashboard_order_status();

create or replace function public.claim_staff_notification(p_order_id text default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare job public.staff_notification_outbox%rowtype; n integer; d jsonb;
begin
 select * into job from public.staff_notification_outbox where sent_at is null and attempts<12
 and next_attempt_at<=now() and (lease_until is null or lease_until<now())
 and (p_order_id is null or order_id=p_order_id) order by next_attempt_at limit 1 for update skip locked;
 if not found then return null; end if;
 update public.staff_notification_outbox set attempts=attempts+1,lease_token=gen_random_uuid(),lease_until=now()+interval '60 seconds'
 where order_id=job.order_id returning * into job;
 select legacy_order_id into strict n from public.order_dashboard_links where secure_order_id=job.order_id;
 select document into strict d from public.secure_orders where id=job.order_id;
 -- No names, phones, addresses, order access tokens or payment secrets leave this RPC.
 return jsonb_build_object('orderId',job.order_id,'legacyOrderId',n,'leaseToken',job.lease_token,
 'total',d->'total','fulfillmentType',d->'fulfillmentType','deliveryDate',d->'deliveryDate','deliverySlot',d->'deliverySlot');
end $$;
create or replace function public.finish_staff_notification(p_order_id text,p_lease_token uuid,p_error text default null)
returns boolean language plpgsql security invoker set search_path='' as $$
declare done text;
begin
 update public.staff_notification_outbox set sent_at=case when p_error is null then now() else null end,
 last_error=case when p_error is null then null else left(p_error,80) end,lease_until=null,lease_token=null,
 next_attempt_at=now()+make_interval(secs=>least(3600,(30*power(2,least(attempts,7)))::integer))
 where order_id=p_order_id and lease_token=p_lease_token and sent_at is null returning order_id into done;
 return done is not null;
end $$;
revoke all on function public.project_order_to_dashboard(text),public.on_secure_order_created(),public.sync_dashboard_order_status(),public.claim_staff_notification(text),public.finish_staff_notification(text,uuid,text) from public,anon,authenticated;
grant execute on function public.project_order_to_dashboard(text),public.on_secure_order_created(),public.sync_dashboard_order_status(),public.claim_staff_notification(text),public.finish_staff_notification(text,uuid,text) to service_role;
-- Versioned RPC prevents an application deploy from silently using an older unbridged schema.
create or replace function public.place_store_order(p_order jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare result jsonb;
begin
 result:=public.place_secure_order(p_order);
 perform public.project_order_to_dashboard(result->'record'->>'id');
 return result;
end $$;
revoke all on function public.place_store_order(jsonb) from public,anon,authenticated;
grant execute on function public.place_store_order(jsonb) to service_role;
notify pgrst,'reload schema';

commit;
